			if gtk.GTKGTK4 {
				gtk.GTK4Gtk_css_provider_load_from_data(provider, gtk.ConverterWcsToMbcs(value.(string), true), int64(-1))
			} else {
				gtk.GTK3Gtk_css_provider_load_from_data(provider, gtk.ConverterWcsToMbcs(value.(string), true), int64(-1), nil)
			}
