func (this *Widget) ConvertPangoFontDescriptionToCss(fontDescription int64) string {
	var css string = "* { "
	var fontMask int32 = gtk.OSPango_font_description_get_set_fields(fontDescription)
	if (fontMask & gtk.OSPANGO_FONT_MASK_FAMILY) != 0 {
		var fontFamily int64 = gtk.OSPango_font_description_get_family(fontDescription)
		css += fmt.Sprintf("font-family: \"%s\";", gtk.ConverterCCharPtrToJavaString(fontFamily, false))
	}
	if (fontMask & gtk.OSPANGO_FONT_MASK_WEIGHT) != 0 {
		var fontWeight int32 = gtk.OSPango_font_description_get_weight(fontDescription)
		var weightString string
		if fontWeight < gtk.OSPANGO_WEIGHT_BOLD {
			weightString = "normal"
		} else {
			weightString = "bold"
		}
		css += fmt.Sprintf("font-weight: %s;", weightString)
	}
	if (fontMask & gtk.OSPANGO_FONT_MASK_STYLE) != 0 {
		var fontStyle int32 = gtk.OSPango_font_description_get_style(fontDescription)
		var styleString string
		switch fontStyle {
		case gtk.OSPANGO_STYLE_NORMAL:
			styleString = "normal"
			break
		case gtk.OSPANGO_STYLE_ITALIC:
			styleString = "italic"
			break
		default:
			styleString = ""
			break
		}
		css += fmt.Sprintf("font-style: %s;", styleString)
	}
	if (fontMask & gtk.OSPANGO_FONT_MASK_SIZE) != 0 {
		var fontSize int32 = gtk.OSPango_font_description_get_size(fontDescription)
		css += fmt.Sprintf("%spt;", fmt.Sprintf("font-size: %d", fontSize/gtk.OSPANGO_SCALE))
	}
	css += " } "
	return css
}

